(() => {
  const style = document.createElement('style');
  style.textContent = '.option-preview{display:block;width:100%;aspect-ratio:1;background-color:var(--es-line,var(--line));background-repeat:no-repeat;overflow:hidden;flex:none}.option-preview[hidden]{display:none!important}.character-previews{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px;margin-top:12px}.character-choice{padding:0;overflow:hidden;text-align:left}.character-choice span:last-child{display:block;padding:8px;font-size:12px}.character-choice[aria-pressed=true]{outline:2px solid var(--es-accent);outline-offset:-2px}@media(max-width:420px){.character-previews{grid-template-columns:repeat(2,minmax(0,1fr))}}';
  document.head.append(style);
  const reveal = el => {el.style.backgroundImage = 'url("'+el.dataset.thumbnail+'")';};
  const observer = typeof IntersectionObserver === 'function' ? new IntersectionObserver(entries=>{entries.forEach(e=>{if(!e.target.isConnected){observer.unobserve(e.target);}else if(e.isIntersecting){reveal(e.target);observer.unobserve(e.target);}});},{rootMargin:'300px'}) : null;
  window.decorateThumbnail = (el,kind,key) => {
    const data = THUMBNAILS[kind]?.[key];
    if(!data)return;
    el.classList.add('option-preview');el.dataset.thumbnail=data.atlas;
    el.style.backgroundSize=(data.cols*100)+'% '+(data.rows*100)+'%';
    el.style.backgroundPosition=(data.cols===1?0:(data.tile%data.cols)*100/(data.cols-1))+'% '+(data.rows===1?0:Math.floor(data.tile/data.cols)*100/(data.rows-1))+'%';
    if(observer)observer.observe(el);else reveal(el);
  };
})();
